def sort_numbers(numbers: str) -> str:
    numeral_mapping = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3,
        'four': 4, 'five': 5, 'six': 6, 'seven': 7,
        'eight': 8, 'nine': 9
    }

    # Split the input string into words
    words = numbers.split()

    # Convert words to numbers
    try:
        nums = [numeral_mapping[word] for word in words]
    except KeyError:
        return ''  # If there's an invalid numeral, return empty

    # Sort the numbers
    nums.sort()

    # Convert numbers back to words
    sorted_words = [list(numeral_mapping.keys())[list(numeral_mapping.values()).index(num)] for num in nums]

    # Join the sorted words into a string and return
    return ' '.join(sorted_words)

